# Evaluate polygon between adjacent tracks in demo2 via point-in-polygon at centers
tracks={8:[(4,4),(5,3)],13:[(4,9),(9,4)],18:[(5,13),(13,5)],22:[(7,15),(15,7)]}
def polycontains(pt,poly):
 x,y=pt # row,col
 inside=False
 for i in range(len(poly)):
  x1,y1=poly[i]; x2,y2=poly[(i+1)%len(poly)]
  if ((y1>y)!=(y2>y)) and (x < (x2-x1)*(y-y1)/(y2-y1)+x1): inside=not inside
 return inside
