 print(ka,kb, {r:[c for rr,c in cells if rr==r] for r in range(16) if any(rr==r for rr,c in cells)})

def pip_rc(pt,poly):
 y,x=pt # row,col
 inside=False
 for i in range(len(poly)):
  y1,x1=poly[i];y2,x2=poly[(i+1)%len(poly)]
  if ((y1>y)!=(y2>y)):
