from scipy.spatial import ConvexHull

def hull_fill(line1,line2, sample_center=True):
 pts=[(r, r+c) for r,c in line1+line2]
 hull=ConvexHull(pts)
 verts=[pts[i] for i in hull.vertices]
 cells=set()
 for r in range(16):
  for c in range(16):
   # coordinates of cell center: (r+.5, r+c+1)
   p=(r+.5,r+c+1) if sample_center else (r,r+c)
   if pip_rc(p, verts):cells.add((r,c))
 return cells
# point-in polygon accepts (row,k) vertices interpreted correctly
for center in [True,False]:
 allcells=set()
 for a,b in [(tracks[8],tracks[13]),(tracks[13],tracks[18]),(tracks[18],tracks[22])]:allcells|=hull_fill(a,b,center)
 print('center',center)
 print({r:[c for rr,c in sorted(allcells) if rr==r] for r in range(16) if any(rr==r for rr,c in allcells)})

def pairband(l1,l2,k1,k2,center=True):
 pts=[(r,r+c) for r,c in l1+l2]; hull=ConvexHull(pts); verts=[pts[i] for i in hull.vertices]
 cells=set()
 for r in range(16):
  for c in range(16):
   kk=r+c
   p=(r+.5,kk+1) if center else (r,kk)
   if k1<kk<k2 and pip_rc(p,verts):cells.add((r,c))
 return cells
for center in [True,False]:
